import backtrader as bt


class EmaCrossoverStrategy(bt.Strategy):
    params = (
        ('FAST', 21),
        ('SLOW', 50),
        ('UNITS', 10000),
    )

    def __init__(self):
        self.ema_fast = bt.indicators.EMA(self.data.close, period=self.p.FAST)
        self.ema_slow = bt.indicators.EMA(self.data.close, period=self.p.SLOW)
        self.crossover = bt.indicators.CrossOver(self.ema_fast, self.ema_slow)
        self.orders = []

    def log(self, txt):
        dt = self.datas[0].datetime.datetime(0)
        print('%s, %s' % (dt.isoformat(), txt))

    def notify_order(self, order):
        if order.status in (order.Submitted, order.Accepted):
            return

        if order in self.orders:
            self.orders.remove(order)

        if order.status == order.Completed:
            side = 'BUY' if order.isbuy() else 'SELL'
            self.log('%s EXECUTED, price=%.2f, size=%d' % (
                side, order.executed.price, order.executed.size))
        elif order.status in (order.Canceled, order.Margin, order.Rejected):
            self.log('ORDER %s' % order.getstatusname())

    def notify_trade(self, trade):
        if trade.isclosed:
            self.log('TRADE CLOSED, pnl=%.2f, pnlcomm=%.2f' % (
                trade.pnl, trade.pnlcomm))

    def next(self):
        if self.orders:
            return

        if self.crossover > 0:
            if self.position.size < 0:
                self.orders.append(self.close())
            self.orders.append(self.buy(size=self.p.UNITS))
        elif self.crossover < 0:
            if self.position.size > 0:
                self.orders.append(self.close())
            self.orders.append(self.sell(size=self.p.UNITS))
